const RoomGrid = ({ rooms }) => {
  console.log('Rendering RoomGrid with rooms:', rooms);

  return (
    <div className="room-grid">
      {rooms.map((room, index) => (
        <div key={index} className={`room ${room ? 'booked' : ''}`}></div>
      ))}
    </div>
  );
};

export default RoomGrid;
